from types import SimpleNamespace
from mlflow.gateway.providers.anthropic import AnthropicAdapter
from mlflow.gateway.providers.vertex_ai import _VertexAIClaudeAdapter

config = SimpleNamespace(model=SimpleNamespace(name='claude-sonnet-4-5'))
choices = [(None, None), ('none', {'type': 'none'}), ('auto', {'type': 'auto'}), ('required', {'type': 'any'}), ({'type': 'function', 'function': {'name': 'get_weather'}}, {'type': 'tool', 'name': 'get_weather'})]
count = 0
for adapter in (AnthropicAdapter, _VertexAIClaudeAdapter):
    for transform in (adapter.chat_to_model, adapter.chat_streaming_to_model):
        for parallel in (False, True, None, 'omitted'):
            for choice, expected in choices:
                payload = {'messages': [{'role': 'user', 'content': 'Hello'}]}
                if choice is not None:
                    payload['tool_choice'] = choice
                if parallel "'!= '"'omitted':
                    payload['parallel_tool_calls'] = parallel
                result = transform(payload, config)
                assert 'parallel_tool_calls' not in result
                if expected is None:
                    assert 'tool_choice' not in result
                else:
                    expected = dict(expected)
                    if parallel is False and choice "'!= '"'none':
                        expected['disable_parallel_tool_use'] = True
                    assert result['tool_choice'] == expected
                count += 1
print(f'Passed {count} direct adapter checks')
